// Soft-delete an add-on and remove its product assignments. The deleted resource is returned for audit and reconciliation workflows. OAuth callers use the admin grant and select a store with X-STORE. Current membership and role permissions apply to every request.
func (s *AddOnService) Delete(ctx context.Context, addon int, opts ...RequestOption) error {
	opts = append([]RequestOption{withOperation("deleteAddOn", false)}, opts...)
	_, err := s.client.request(ctx, "DELETE", fmt.Sprintf("/v2/addons/%s", url.PathEscape(fmt.Sprint(addon))), nil, nil, nil, opts)
	return err
}

func (s *AddOnService) DeleteWithResponse(ctx context.Context, addon int, opts ...RequestOption) (*RawResponse[struct{}], error) {
	var metadata *responseMetadata
	captureOpts := append(opts, withResponseMetadata(&metadata))
	if err := s.Delete(ctx, addon, captureOpts...); err != nil {
		return nil, err
	}
	return rawResponse(struct{}{}, metadata), nil
}
